SELECT ssod.EXT_AREA_ID AS areaId, ssod.EXT_AREA_CODE AS areaCode, ssod.EXT_AREA_NAME AS areaName, ssod.CEEA_ORGANIZATION_ID AS organizationId, ssod.CEEA_ORGANIZATION_NAME AS organizationCode, ssod.CEEA_ORGANIZATION_CODE AS organizationName, ssod.MATERIAL_ID AS materialId, ssod.MATERIAL_CODE AS MATERIAL_CODE, ssod.MATERIAL_NAME AS materialName, ssod.SPECIFICATION AS model, ssod.UNIT AS unit, ssod.UNIT_CODE AS unitCode, ssod.ORDER_NUM AS orderNum, ssod.EXT_BRAND AS brand, ssod.CEEA_UNIT_NO_TAX_PRICE AS priceTax, ssod.CEEA_TAX_RATE AS taxRate, ssod.CEEA_TAX_KEY AS taxRateCode, ssod.CEEA_UNIT_TAX_PRICE AS ratePrice, ssod.NO_TAX_AMOUNT AS moneyAmount, ssod.NO_TAX_AMOUNT AS priceTotal, sso.VENDOR_ID AS supId, sso.VENDOR_CODE AS supCode, sso.VENDOR_NAME AS supName, sso.CEEA_PURCHASE_ORDER_DATE AS orderDate, sso.CEEA_EMP_USER_ID AS buyUserId, sso.CEEA_EMP_USERNAME AS buyUserName, ssod.CEEA_CONTRACT_LINE_ID AS contractId, ssod.CEEA_CONTRACT_NO AS contractCode, ssod.CEEA_CONTRACT_NUM AS contractNum, ssod.EXT_BUY_TYPE AS buyType, ssod.CATEGORY_ID, ssod.CATEGORY_CODE, ssod.CATEGORY_NAME FROM scc_sc_order_detail ssod LEFT JOIN scc_sc_order sso ON ssod.ORDER_ID = sso.ORDER_ID
ssod.CATEGORY_ID in
#{item}
AND ssod.EXT_BRAND LIKE CONCAT('%%', #{pullQuery.brand,jdbcType=VARCHAR}, '%')
AND ssod.MATERIAL_CODE in
#{item}
AND ssod.ORDER_NUM ${pullQuery.orderNum,jdbcType=VARCHAR}
AND ssod.CEEA_AMOUNT_EXCLUDING_TAX ${pullQuery.buyMoney,jdbcType=VARCHAR}
AND ssod.EXT_AREA_CODE in
#{item}
AND sso.VENDOR_CODE IN
#{item}
AND sso.ORGANIZATION_CODE IN
#{item}
AND sso.CEEA_EMP_USER_ID IN
#{item}
AND sso.ORDER_STATUS IN
#{item}
AND sso.CEEA_PURCHASE_ORDER_DATE BETWEEN #{pullQuery.lastYearOrderDateStart} AND #{pullQuery.lastYearOrderDateEnd}
AND sso.CEEA_PURCHASE_ORDER_DATE BETWEEN #{pullQuery.lastLastYearOrderDateStart} AND #{pullQuery.lastLastYearOrderDateEnd}
